setup.patch:
diff --git a/lib/l10n/strings_walk.dart b/lib/l10n/strings_walk.dart
--- a/lib/l10n/strings_walk.dart
+++ b/lib/l10n/strings_walk.dart
@@ -405,11 +405,6 @@
           ? '1 debrief is waiting for you'
           : '$n debriefs are waiting for you')
       : (n == 1 ? '1 débrief t\'attend' : '$n débriefs t\'attendent');
-
-  /// Sous-titre de l'écran s92b quand il reste des balades.
-  String pendingHeader(int n) => _en
-      ? '$n walk${n > 1 ? 's' : ''} · the order doesn\'t matter'
-      : '$n balade${n > 1 ? 's' : ''} · l\'ordre n\'a pas d\'importance';

   /// Relatif court des lignes en attente.
   String agoMinutes(int m) => _en ? '$m min ago' : 'il y a $m min';
diff --git a/lib/ui/walk/pending_debriefs_screen.dart b/lib/ui/walk/pending_debriefs_screen.dart
--- a/lib/ui/walk/pending_debriefs_screen.dart
+++ b/lib/ui/walk/pending_debriefs_screen.dart
@@ -324,7 +324,9 @@
                         // (les lignes « fait à l'instant » restent
                         // affichées) — un libellé de fierté plutôt qu'un
                         // « 0 balade » absurde.
-                        n == 0 ? s.allCaughtUp : s.pendingHeader(n),
+                        n == 0
+                            ? s.allCaughtUp
+                            : '$n balade${n > 1 ? 's' : ''} · l\'ordre n\'a pas d\'importance',
                         style: AppType.caption.copyWith(color: t.inkTertiary),
                       ),
                     ],
